// Benchmark: bmc_safe.c
// Expected: TRUE (bounded model checking within bound k=10)
extern unsigned __VERIFIER_nondet_uint();
extern void __assert_fail(const char *assertion, const char *file,
                          unsigned int line, const char *function);
int main() {
  int x = 1;
  int i = 0;
  while (i < 8) {
    x = x * 2;
    i++;
  }
  if (x != 256) {
    __assert_fail("x == 256", "bmc_safe.c", 13, "main");
  }
  return 0;
}
