class PathFormula:
    """SSA encoding of a concrete program path.

    ``clause_groups`` holds one DNF per edge (a list of alternative
    conjunctions); a path is feasible iff one clause can be picked from every
    group such that the conjunction of all picked clauses is satisfiable.
    """

    def __init__(self):
        self.clause_groups: list[list[list[Constraint]]] = []
        self.steps: list[dict] = []
        self.variables: set[str] = set()
        self.approximated = False

    def add_group(self, clauses: Sequence[Sequence[Constraint]]) -> None:
        self.clause_groups.append([list(clause) for clause in clauses])

    def __repr__(self) -> str:  # pragma: no cover - debugging helper
        return f"PathFormula(groups={len(self.clause_groups)}, steps={len(self.steps)})"


class PathCheckResult:
    """Outcome of a path feasibility query."""

    def __init__(
        self,
        status: str,
        constraints: frozenset = frozenset(),
        model: Optional[dict[str, int]] = None,
        formula: Optional[PathFormula] = None,
    ):
        self.status = status
        self.constraints = constraints
        self.model = model
        self.formula = formula

    @property
    def feasible(self) -> bool:
        return self.status == SAT

    def __repr__(self) -> str:  # pragma: no cover - debugging helper
        return f"PathCheckResult({self.status}, model={self.model})"


class PathFeasibilityChecker:
    """Lightweight constraint solver used to decide path feasibility.

    It answers three kinds of questions:

    * :meth:`check` -- is a set of predicates satisfiable (``SAT``/``UNSAT``)?
    * :meth:`implies` / :meth:`entails` -- is a predicate (set) a logical
      consequence of another set?  This drives the coverage (stop) check.
    * :meth:`check_path` -- is a concrete CFA path feasible, and what input
      values witness it?  This validates counterexamples.

    Reasoning is done by Gaussian elimination on equalities, congruence
    (modulo) reasoning and Fourier-Motzkin elimination with integer tightening;
    see :mod:`cpachecker.analyses.symbolic`.
    """

    def __init__(self, solver: Optional[LinearSolver] = None):
        self.solver = solver or LinearSolver()
        self.stats = {"path_checks": 0, "infeasible_paths": 0}

    # -- predicate level ----------------------------------------------------
    def check(self, predicates: Iterable[Constraint]) -> str:
        return SAT if self.solver.is_sat(frozenset(predicates)) else UNSAT

    def is_satisfiable(self, predicates: Iterable[Constraint]) -> bool:
        return self.solver.is_sat(frozenset(predicates))

    def implies(self, predicates: Iterable[Constraint], target: Constraint) -> bool:
        return self.solver.implies(frozenset(predicates), target)

    def entails(
        self, predicates: Iterable[Constraint], targets: Iterable[Constraint]
    ) -> bool:
        return self.solver.implies_all(frozenset(predicates), targets)

    def model(
        self, predicates: Iterable[Constraint], variables: Iterable[str] = ()
    ) -> Optional[dict[str, int]]:
        return self.solver.find_model(frozenset(predicates), variables)

    # -- path level ---------------------------------------------------------
    def build_path_formula(
        self, edges: Sequence[Optional[CFAEdge]], program_variables: Iterable[str] = ()
    ) -> PathFormula:
        """Encode the sequence of CFA edges in static single assignment form."""
        formula = PathFormula()
        indices: dict[str, int] = {}
        facts: frozenset[Constraint] = frozenset()

        def symbol(name: str) -> str:
            return f"{name}@{indices.get(name, 0)}"

        for name in program_variables:
            formula.variables.add(symbol(name))

        for edge in edges:
            if edge is None:
                continue
            text = edge.expression or ""
            try:
                expr = parse_expression(text) if text else None
            except (ExpressionSyntaxError, IndexError):
                expr = None

            if edge.edge_type == EdgeType.ASSIGNMENT and edge.variable:
                env = (
                    {name: symbol(name) for name in collect_variables(expr)}
                    if expr is not None
                    else {}
                )
                ctx = LinearizeContext(self.solver, facts, env, prefix="__p")
                indices[edge.variable] = indices.get(edge.variable, 0) + 1
                target = LinExpr.variable(symbol(edge.variable))
                formula.variables.add(symbol(edge.variable))
                if expr is None or contains_nondet(expr):
                    # Fresh unconstrained input value.
                    clause: list[Constraint] = list(ctx.extra)
                    if expr is not None and contains_nondet(expr):
                        rhs = linearize(expr, ctx)
                        clause = list(ctx.extra) + [
                            Constraint.equality(target - rhs)
                        ]
                else:
                    rhs = linearize(expr, ctx)
                    clause = list(ctx.extra) + [Constraint.equality(target - rhs)]
                formula.approximated = formula.approximated or ctx.approximated
                formula.add_group([clause])
                facts = facts | frozenset(clause)
                formula.variables.update(constraint_variables(clause))
            elif edge.edge_type in (EdgeType.ASSUME_TRUE, EdgeType.ASSUME_FALSE):
                env = (
                    {name: symbol(name) for name in collect_variables(expr)}
                    if expr is not None
                    else {}
                )
                ctx = LinearizeContext(self.solver, facts, env, prefix="__p")
                clauses = (
                    to_dnf(expr, ctx, edge.edge_type == EdgeType.ASSUME_FALSE)
                    if expr is not None
                    else [[]]
                )
                extra = list(ctx.extra)
                groups = [list(clause) + extra for clause in clauses]
                formula.approximated = formula.approximated or ctx.approximated
                formula.add_group(groups)
                if len(groups) == 1:
                    facts = facts | frozenset(groups[0])
                for clause in groups:
                    formula.variables.update(constraint_variables(clause))
            formula.steps.append(
                {
                    "edge": edge,
                    "description": describe_edge(edge),
                    "symbols": dict(indices),
                }
            )
        return formula

    def check_formula(
        self, formula: PathFormula, node_limit: int = 20000
    ) -> PathCheckResult:
        """Pick one clause per edge such that the conjunction is satisfiable."""
        budget = [node_limit]

        def recurse(index: int, current: frozenset) -> Optional[frozenset]:
            if budget[0] <= 0:  # pragma: no cover - safety valve
                return current
            if index >= len(formula.clause_groups):
                return current
            for clause in formula.clause_groups[index]:
                budget[0] -= 1
                candidate = current | frozenset(clause)
                if not self.solver.is_sat(candidate):
                    continue
                found = recurse(index + 1, candidate)
                if found is not None:
                    return found
            return None

        result = recurse(0, frozenset())
        if result is None:
            return PathCheckResult(UNSAT, formula=formula)
        model = self.solver.find_model(result, formula.variables)
        return PathCheckResult(SAT, constraints=result, model=model, formula=formula)

    def check_path(
        self,
        edges: Sequence[Optional[CFAEdge]],
        program_variables: Iterable[str] = (),
    ) -> PathCheckResult:
        self.stats["path_checks"] += 1
        formula = self.build_path_formula(edges, program_variables)
        result = self.check_formula(formula)
        if not result.feasible:
            self.stats["infeasible_paths"] += 1
        return result

    def witness_values(
        self, formula: PathFormula, model: Optional[dict[str, int]]
    ) -> list[dict]:
        """Variable values at every step of the path (the counterexample witness)."""
        if model is None:
            return []
        witness = []
        for step in formula.steps:
            assignment = {}
            for name, index in step["symbols"].items():
                value = model.get(f"{name}@{index}")
                if value is not None:
                    assignment[name] = value
            witness.append(
                {"edge": step["description"], "values": dict(sorted(assignment.items()))}
            )
        return witness


# ---------------------------------------------------------------------------
# Abstract state and domain
# ---------------------------------------------------------------------------


class PredicateAbstractState(AbstractState):
    """A conjunction of symbolic predicates over the current variable values."""

    __slots__ = ("constraints", "_hash")

    def __init__(self, constraints: Iterable[Constraint] = ()):
        self.constraints = (
            constraints
            if isinstance(constraints, frozenset)
            else frozenset(constraints)
        )
        self._hash = hash(self.constraints)

    @property
    def predicates(self) -> list[str]:
        """The predicates as readable strings (e.g. ``x + y - n == 0``)."""
        return sorted(repr(c) for c in self.constraints)

    def is_false(self) -> bool:
        return FALSE_CONSTRAINT in self.constraints

    def variables(self) -> set[str]:
        return constraint_variables(self.constraints)

    def with_constraints(
        self, constraints: Iterable[Constraint]
    ) -> "PredicateAbstractState":
        return PredicateAbstractState(simplify_constraints(constraints))

    def __eq__(self, other) -> bool:
        return (
            isinstance(other, PredicateAbstractState)
            and other.constraints == self.constraints
        )

    def __hash__(self) -> int:
        return self._hash

    def __repr__(self) -> str:
        return "{" + format_constraints(self.constraints) + "}"


class PredicateDomain(AbstractDomain):
    """Lattice of predicate sets ordered by logical implication."""

    def __init__(self, solver: LinearSolver):
        self.solver = solver

    def is_less_or_equal(self, state1: AbstractState, state2: AbstractState) -> bool:
        assert isinstance(state1, PredicateAbstractState)
        assert isinstance(state2, PredicateAbstractState)
        if state1.constraints == state2.constraints:
            return True
        if state2.constraints <= state1.constraints:
            return True  # syntactically stronger
        return self.solver.implies_all(state1.constraints, state2.constraints)

    def join(self, state1: AbstractState, state2: AbstractState) -> AbstractState:
        """Weakest set of the given predicates implied by both states."""
        assert isinstance(state1, PredicateAbstractState)
        assert isinstance(state2, PredicateAbstractState)
        if state1.is_false():
            return state2
        if state2.is_false():
            return state1
        kept = [c for c in state1.constraints if self.solver.implies(state2.constraints, c)]
        kept += [
            c
            for c in state2.constraints
            if c not in state1.constraints
            and self.solver.implies(state1.constraints, c)
        ]
        return PredicateAbstractState(simplify_constraints(kept))

    def get_top(self) -> AbstractState:
        return PredicateAbstractState()

    def get_bottom(self) -> AbstractState:
        return PredicateAbstractState({FALSE_CONSTRAINT})


# ---------------------------------------------------------------------------
# Transfer relation
# ---------------------------------------------------------------------------


class PredicateTransferRelation(TransferRelation):
    """Strongest post-condition over sets of linear predicates."""

    def __init__(
        self,
        cfa: CFA,
        checker: Optional[PathFeasibilityChecker] = None,
        *,
        widening_threshold: Optional[int] = 40,
        max_predicates: int = 40,
    ):
        self.cfa = cfa
        self.checker = checker or PathFeasibilityChecker()
        self.solver = self.checker.solver
        self.widening_threshold = widening_threshold
        self.max_predicates = max_predicates
        self.approximations = 0
        self.stats = {
            "assignments": 0,
            "assumptions": 0,
            "infeasible_assumptions": 0,
            "assume_splits": 0,
            "widened": 0,
            "approximated_assignments": 0,
        }
        self._visits: dict[int, int] = {}
        self._last_at: dict[int, PredicateAbstractState] = {}

    # -- interface ----------------------------------------------------------
    def get_abstract_successors(
        self, state: AbstractState, precision: Precision, edge: Any = None
    ) -> list[AbstractState]:
        assert isinstance(state, PredicateAbstractState)
        if edge is None:
            raise ValueError("PredicateCPA needs a CFA edge")
        if state.is_false():
            return []

        kind = edge.edge_type
        if kind == EdgeType.ASSIGNMENT and edge.variable:
            successors = self._assign(state, edge)
        elif kind in (EdgeType.ASSUME_TRUE, EdgeType.ASSUME_FALSE):
            successors = self._assume(state, edge, kind == EdgeType.ASSUME_TRUE)
        else:
            successors = [state]
        return [self._post_process(edge, s) for s in successors]

    # -- operations ---------------------------------------------------------
    def _assign(
        self, state: PredicateAbstractState, edge: CFAEdge
    ) -> list[PredicateAbstractState]:
        self.stats["assignments"] += 1
        var = edge.variable
        try:
            expr = parse_expression(edge.expression) if edge.expression else None
        except (ExpressionSyntaxError, IndexError):  # pragma: no cover - robustness
            expr = None

        if expr is None:
            self._note_approximation()
            return [state.with_constraints(eliminate_variable(state.constraints, var))]

        ctx = LinearizeContext(self.solver, state.constraints, prefix=AUX_PREFIX)
        rhs = linearize(expr, ctx)
        if ctx.approximated:
            self.stats["approximated_assignments"] += 1
            self._note_approximation()

        aux = ctx.new_symbol()
        combined = set(state.constraints) | set(ctx.extra)
        combined.add(Constraint.equality(LinExpr.variable(aux) - rhs))
        # Existentially quantify the old value of `var`, then rename the fresh
        # symbol holding the new value back to `var`.
        if not self._has_equality_for(combined, var):
            self._note_approximation()
        eliminated = eliminate_variable(combined, var)
        renamed = rename_variable(eliminated, aux, var)
        return [state.with_constraints(renamed)]

    def _assume(
        self, state: PredicateAbstractState, edge: CFAEdge, want_true: bool
    ) -> list[PredicateAbstractState]:
        self.stats["assumptions"] += 1
        ctx = LinearizeContext(self.solver, state.constraints, prefix=AUX_PREFIX)
        clauses = condition_clauses(edge.expression or "", ctx, negated=not want_true)
        if ctx.approximated:
            self._note_approximation()
        extra = list(ctx.extra)
        successors: list[PredicateAbstractState] = []
        for clause in clauses:
            candidate = simplify_constraints(
                list(state.constraints) + extra + list(clause)
            )
            if FALSE_CONSTRAINT in candidate or not self.solver.is_sat(candidate):
                continue
            successors.append(PredicateAbstractState(candidate))
        if not successors:
            self.stats["infeasible_assumptions"] += 1
        elif len(successors) > 1:
            self.stats["assume_splits"] += 1
        return successors

    def _post_process(
        self, edge: CFAEdge, state: PredicateAbstractState
    ) -> PredicateAbstractState:
        """Optional widening; a safety net that keeps long loops converging."""
        if self.widening_threshold is None:
            return state
        target = edge.target
        visits = self._visits.get(target, 0) + 1
        self._visits[target] = visits
        previous = self._last_at.get(target)
        self._last_at[target] = state
        if visits <= self.widening_threshold or previous is None:
            return state
        widened = PredicateDomain(self.solver).join(state, previous)
        if widened.constraints != state.constraints:
            self.stats["widened"] += 1
            self._note_approximation()
            return widened
        return state

    def _has_equality_for(self, constraints: Iterable[Constraint], var: str) -> bool:
        return any(c.op == EQ and var in c.lin.coeffs for c in constraints)

    def _note_approximation(self) -> None:
        self.approximations += 1

    @property
    def exact(self) -> bool:
        """True while no transfer has lost information."""
        return self.approximations == 0


# ---------------------------------------------------------------------------
# CPA
# ---------------------------------------------------------------------------


class PredicateStopOperator(StopOperator):
    """Covered iff the new state is logically implied by a reached state."""

    def __init__(self, domain: PredicateDomain):
        self.domain = domain

    def stop(self, state: AbstractState, reached, precision: Precision) -> bool:
        for other in reached:
            if self.domain.is_less_or_equal(state, other):
                return True
        return False


class PredicateCPA(ConfigurableProgramAnalysis):
    """CPA tracking symbolic predicates; merge^sep, stop by implication."""

    def __init__(
        self,
        cfa: CFA,
        checker: Optional[PathFeasibilityChecker] = None,
        *,
        widening_threshold: Optional[int] = 40,
        initial_constraints: Iterable[Constraint] = (),
    ):
        self.cfa = cfa
        self.checker = checker or PathFeasibilityChecker()
        self.solver = self.checker.solver
        self.initial_constraints = frozenset(initial_constraints)
        self._domain = PredicateDomain(self.solver)
        self._transfer = PredicateTransferRelation(
            cfa, self.checker, widening_threshold=widening_threshold
        )
        self._merge = MergeSepOperator()
        self._stop = PredicateStopOperator(self._domain)

    def get_abstract_domain(self) -> AbstractDomain:
        return self._domain

    def get_transfer_relation(self) -> TransferRelation:
        return self._transfer

    def get_merge_operator(self) -> MergeOperator:
        return self._merge

    def get_stop_operator(self) -> StopOperator:
        return self._stop

    def get_initial_state(self, node_id: int) -> AbstractState:
        # No predicates: every variable may hold any value.
        return PredicateAbstractState(self.initial_constraints)

    def get_initial_precision(self) -> Precision:
        return TrivialPrecision()


def extract_predicate_state(state: AbstractState) -> Optional[PredicateAbstractState]:
    if isinstance(state, PredicateAbstractState):
        return state
    if isinstance(state, CompositeState):
        found = state.get_component(PredicateAbstractState)
        if isinstance(found, PredicateAbstractState):
            return found
    return None


def path_edges(error_path: Sequence[dict]) -> list[CFAEdge]:
    """The CFA edges of an error path produced by :class:`CPAAlgorithm`."""
    return [
        element["edge_object"]
        for element in error_path
        if element.get("edge_object") is not None
    ]


# ---------------------------------------------------------------------------
# Entry point
# ---------------------------------------------------------------------------


def run_predicate_analysis(
    cfa: CFA, timelimit: Optional[float] = 900
) -> VerificationResult:
    """Verify ``cfa`` with the composite location + predicate analysis."""
    checker = PathFeasibilityChecker()
    location_cpa = LocationCPA(cfa)
    predicate_cpa = PredicateCPA(cfa, checker)
    composite = CompositeCPA(cfa, [location_cpa, predicate_cpa])
    transfer = predicate_cpa.get_transfer_relation()

    deadline = time.monotonic() + timelimit if timelimit else None
    spurious = 0

    def on_error(state: AbstractState) -> str:
        """Confirm a counterexample before reporting it."""
        nonlocal spurious
        if transfer.exact:
            # Every transfer along the path was precise: the abstract path is a
            # real program path, no confirmation needed.
            return "report"
        result = checker.check_path(algorithm.edges_to(state), cfa.variables)
        if result.feasible:
            return "report"
        spurious += 1
        return "prune"

    algorithm = CPAAlgorithm(
        composite, cfa, deadline=deadline, error_action=on_error, max_states=200_000
    )
    outcome = algorithm.run()

    statistics = {
        "algorithm": "predicateAnalysis (symbolic predicates + path feasibility)",
        "cpas": "LocationCPA x PredicateCPA",
        "reached_states": len(outcome.reached),
        "states_popped": outcome.stats.get("popped", 0),
        "states_covered": outcome.stats.get("covered", 0),
        "assignments": transfer.stats["assignments"],
        "assumptions": transfer.stats["assumptions"],
        "infeasible_assumptions": transfer.stats["infeasible_assumptions"],
        "assume_splits": transfer.stats["assume_splits"],
        "solver_queries": checker.solver.stats["sat_calls"],
        "solver_cache_hits": checker.solver.stats["cache_hits"],
        "unsat_queries": checker.solver.stats["unsat"],
        "path_checks": checker.stats["path_checks"],
        "abstraction_exact": transfer.exact,
    }
    if spurious:
        statistics["infeasible_error_paths_pruned"] = spurious

    if outcome.error_found:
        edges = path_edges(outcome.error_path)
        check = checker.check_path(edges, cfa.variables)
        witness = checker.witness_values(check.formula, check.model) if check.formula else []
        statistics["counterexample_length"] = len(outcome.error_path)
        statistics["counterexample_path"] = " | ".join(
            element["edge"] for element in outcome.error_path if element["edge"]
        )
        statistics["counterexample_feasible"] = check.status
        if check.model:
            statistics["counterexample_inputs"] = ", ".join(
                f"{name}={value}"
                for name, value in sorted(check.model.items())
                if name.endswith("@0") or "@" not in name
            )
        if witness:
            statistics["witness"] = " ; ".join(
                f"{step['edge']} -> {step['values']}" for step in witness if step["edge"]
            )
        predicate_state = extract_predicate_state(outcome.error_state)
        if predicate_state is not None:
            statistics["error_predicates"] = format_constraints(
                predicate_state.constraints
            )
        return VerificationResult(
            verdict=Verdict.FALSE,
            property_violated="assertion",
            error_path=outcome.error_path,
            statistics=statistics,
        )

    if outcome.timed_out or outcome.state_limit_hit:
        statistics["reason"] = (
            "time limit exhausted" if outcome.timed_out else "state limit exhausted"
        )
        return VerificationResult(verdict=Verdict.UNKNOWN, statistics=statistics)

    if spurious:
        statistics["reason"] = (
            "infeasible abstract error paths were pruned; abstraction too coarse"
        )
        return VerificationResult(verdict=Verdict.UNKNOWN, statistics=statistics)

    statistics["proof"] = (
        "fixed point reached: every abstract path to the error location is infeasible"
    )
    return VerificationResult(verdict=Verdict.TRUE, statistics=statistics)

"""Symbolic linear-arithmetic machinery.

This module is the shared "solver layer" used by the predicate analysis
(``cpachecker_v1``) and by BMC / k-induction (``cpachecker_v3``).  It contains

* a small recursive-descent parser for the C expression subset produced by
  :mod:`cpachecker.parser` (:func:`parse_expression`),
* :class:`LinExpr` -- linear expressions over integer variables with exact
  rational coefficients,
* :class:`Constraint` -- normalised linear equalities, inequalities and
  congruences (``lin == 0``, ``lin >= 0``, ``lin = 0 (mod m)``),
* :class:`LinearSolver` -- a lightweight decision procedure for conjunctions of
  such constraints (Gaussian elimination + congruence reasoning +
  Fourier-Motzkin with integer tightening) including implication checks and
  model search,
* :func:`linearize` / :func:`to_dnf` -- translation of C expressions into linear
  expressions and into disjunctive normal form over :class:`Constraint`.

Everything works over mathematical integers; no external SMT solver is used.
"""

from __future__ import annotations

import re
from fractions import Fraction
from math import gcd
from typing import Any, Iterable, Optional, Sequence

# ---------------------------------------------------------------------------
# C helpers
# ---------------------------------------------------------------------------

NONDET_PREFIX = "__VERIFIER_nondet"


def c_div(a: int, b: int) -> int:
    """Integer division with C semantics (truncation towards zero)."""
    if b == 0:
        raise ZeroDivisionError
    quotient = abs(a) // abs(b)
    return quotient if (a >= 0) == (b >= 0) else -quotient


def c_mod(a: int, b: int) -> int:
    """Remainder with C semantics (sign follows the dividend)."""
    return a - b * c_div(a, b)


# ---------------------------------------------------------------------------
# Expression AST + parser
# ---------------------------------------------------------------------------


class Expr:
    """Base class of the expression AST."""

    __slots__ = ()


class Num(Expr):
    __slots__ = ("value",)

    def __init__(self, value: int):
        self.value = int(value)

    def __repr__(self) -> str:
        return str(self.value)


class Var(Expr):
    __slots__ = ("name",)

    def __init__(self, name: str):
        self.name = name

    def __repr__(self) -> str:
        return self.name


class Unary(Expr):
    __slots__ = ("op", "operand")

    def __init__(self, op: str, operand: Expr):
        self.op = op
        self.operand = operand

    def __repr__(self) -> str:
        return f"({self.op}{self.operand!r})"


class Binary(Expr):
    __slots__ = ("op", "left", "right")

    def __init__(self, op: str, left: Expr, right: Expr):
        self.op = op
        self.left = left
        self.right = right

    def __repr__(self) -> str:
        return f"({self.left!r} {self.op} {self.right!r})"


class Call(Expr):
    __slots__ = ("name", "args")

    def __init__(self, name: str, args: Sequence[Expr]):
        self.name = name
        self.args = tuple(args)

    @property
    def is_nondet(self) -> bool:
        return self.name.startswith(NONDET_PREFIX)

    def __repr__(self) -> str:
        return f"{self.name}({', '.join(repr(a) for a in self.args)})"


class StringLit(Expr):
    __slots__ = ("text",)

    def __init__(self, text: str):
        self.text = text

    def __repr__(self) -> str:
        return self.text


_TOKEN_RE = re.compile(
    r"""\s*(?:
        (?P<num>\d+[uUlL]*)
      | (?P<ident>[A-Za-z_][A-Za-z_0-9]*)
      | (?P<string>"[^"]*")
      | (?P<op><<|>>|<=|>=|==|!=|&&|\|\||[+\-*/%<>!&|^~(),])
    )""",
    re.VERBOSE,
)

# Binary operator precedence, lowest binds last.
_PRECEDENCE = [
    ("||",),
    ("&&",),
    ("|",),
    ("^",),
    ("&",),
    ("==", "!="),
    ("<", "<=", ">", ">="),
    ("<<", ">>"),
    ("+", "-"),
    ("*", "/", "%"),
]


class ExpressionSyntaxError(ValueError):
    pass


class _ExprParser:
    def __init__(self, text: str):
        self.tokens: list[tuple[str, str]] = []
        pos = 0
        while pos < len(text):
            match = _TOKEN_RE.match(text, pos)
            if not match:
                if text[pos].isspace():
                    pos += 1
                    continue
                raise ExpressionSyntaxError(f"cannot tokenize {text!r} at {pos}")
            pos = match.end()
            kind = match.lastgroup
            self.tokens.append((kind, match.group(kind)))
        self.index = 0

    def peek(self) -> Optional[tuple[str, str]]:
        return self.tokens[self.index] if self.index < len(self.tokens) else None

    def next(self) -> tuple[str, str]:
        token = self.tokens[self.index]
        self.index += 1
        return token

    def accept_op(self, *values: str) -> Optional[str]:
        token = self.peek()
        if token and token[0] == "op" and token[1] in values:
            self.index += 1
            return token[1]
        return None

    def expect_op(self, value: str) -> None:
        if self.accept_op(value) is None:
            raise ExpressionSyntaxError(f"expected {value!r}")

    def parse(self) -> Expr:
        expr = self.parse_binary(0)
        if self.peek() is not None:
            raise ExpressionSyntaxError(f"trailing tokens in expression: {self.peek()}")
        return expr

    def parse_binary(self, level: int) -> Expr:
        if level >= len(_PRECEDENCE):
            return self.parse_unary()
        left = self.parse_binary(level + 1)
        while True:
            op = self.accept_op(*_PRECEDENCE[level])
            if op is None:
                return left
            right = self.parse_binary(level + 1)
            left = Binary(op, left, right)

    def parse_unary(self) -> Expr:
        op = self.accept_op("-", "+", "!", "~")
        if op is not None:
            return Unary(op, self.parse_unary())
        return self.parse_primary()

    def parse_primary(self) -> Expr:
        token = self.peek()
        if token is None:
            raise ExpressionSyntaxError("unexpected end of expression")
        kind, value = token
        if kind == "num":
            self.next()
            return Num(int(value.rstrip("uUlL")))
        if kind == "string":
            self.next()
            return StringLit(value)
        if kind == "ident":
            self.next()
            if self.accept_op("(") is not None:
                args: list[Expr] = []
                if self.accept_op(")") is None:
                    while True:
                        args.append(self.parse_binary(0))
                        if self.accept_op(",") is not None:
                            continue
                        self.expect_op(")")
                        break
                return Call(value, args)
            return Var(value)
        if kind == "op" and value == "(":
            self.next()
            inner = self.parse_binary(0)
            self.expect_op(")")
            return inner
        raise ExpressionSyntaxError(f"unexpected token {value!r}")


_PARSE_CACHE: dict[str, Expr] = {}


def parse_expression(text: str) -> Expr:
    """Parse a C expression; results are cached because CFA edges repeat."""
    cached = _PARSE_CACHE.get(text)
    if cached is None:
        cached = _ExprParser(text).parse()
        _PARSE_CACHE[text] = cached
    return cached


def collect_variables(expr: Expr, out: Optional[set[str]] = None) -> set[str]:
    """All identifiers read by ``expr``."""
    if out is None:
        out = set()
    if isinstance(expr, Var):
        out.add(expr.name)
    elif isinstance(expr, Unary):
        collect_variables(expr.operand, out)
    elif isinstance(expr, Binary):
        collect_variables(expr.left, out)
        collect_variables(expr.right, out)
    elif isinstance(expr, Call):
        for arg in expr.args:
            collect_variables(arg, out)
    return out


def contains_nondet(expr: Expr) -> bool:
    if isinstance(expr, Call):
        return expr.is_nondet or any(contains_nondet(a) for a in expr.args)
    if isinstance(expr, Unary):
        return contains_nondet(expr.operand)
    if isinstance(expr, Binary):
        return contains_nondet(expr.left) or contains_nondet(expr.right)
    return False


# ---------------------------------------------------------------------------
# Linear expressions
# ---------------------------------------------------------------------------

ZERO = Fraction(0)
ONE = Fraction(1)


class LinExpr:
    """``sum(coeff * var) + const`` with exact rational coefficients."""

    __slots__ = ("coeffs", "const", "_key", "_hash")

    def __init__(self, coeffs: Optional[dict[str, Fraction]] = None, const: Any = 0):
        clean: dict[str, Fraction] = {}
        if coeffs:
            for name, coeff in coeffs.items():
                value = Fraction(coeff)
                if value:
                    clean[name] = value
        self.coeffs = clean
        self.const = Fraction(const)
        self._key = (tuple(sorted(clean.items())), self.const)
        self._hash = hash(self._key)

    # -- constructors -------------------------------------------------------
    @staticmethod
    def constant(value: Any) -> "LinExpr":
        return LinExpr({}, value)

    @staticmethod
    def variable(name: str, coeff: Any = 1) -> "LinExpr":
        return LinExpr({name: Fraction(coeff)}, 0)

    # -- queries ------------------------------------------------------------
    def is_constant(self) -> bool:
        return not self.coeffs

    def variables(self) -> Iterable[str]:
        return self.coeffs.keys()

    def coeff(self, name: str) -> Fraction:
        return self.coeffs.get(name, ZERO)

    # -- arithmetic ---------------------------------------------------------
    def __add__(self, other: "LinExpr") -> "LinExpr":
        coeffs = dict(self.coeffs)
        for name, coeff in other.coeffs.items():
            coeffs[name] = coeffs.get(name, ZERO) + coeff
        return LinExpr(coeffs, self.const + other.const)

    def __sub__(self, other: "LinExpr") -> "LinExpr":
        return self + other.negate()

    def negate(self) -> "LinExpr":
        return LinExpr({n: -c for n, c in self.coeffs.items()}, -self.const)

    def scale(self, factor: Any) -> "LinExpr":
        f = Fraction(factor)
        if f == 0:
            return LinExpr()
        return LinExpr({n: c * f for n, c in self.coeffs.items()}, self.const * f)

    def substitute(self, var: str, replacement: "LinExpr") -> "LinExpr":
        coeff = self.coeffs.get(var)
        if coeff is None:
            return self
        rest = LinExpr({n: c for n, c in self.coeffs.items() if n != var}, self.const)
        return rest + replacement.scale(coeff)

    def rename(self, mapping: dict[str, str]) -> "LinExpr":
        if not any(name in mapping for name in self.coeffs):
            return self
        coeffs: dict[str, Fraction] = {}
        for name, coeff in self.coeffs.items():
            target = mapping.get(name, name)
            coeffs[target] = coeffs.get(target, ZERO) + coeff
        return LinExpr(coeffs, self.const)

    def integer_multiplier(self) -> int:
        """Smallest positive integer ``m`` such that ``m * self`` is integral."""
        multiplier = 1
        for value in list(self.coeffs.values()) + [self.const]:
            denominator = value.denominator
            multiplier = multiplier * denominator // gcd(multiplier, denominator)
        return multiplier

    def evaluate(self, values: dict[str, Any]) -> Optional[Fraction]:
        total = self.const
        for name, coeff in self.coeffs.items():
            if name not in values:
                return None
            total += coeff * Fraction(values[name])
        return total

    # -- object protocol ---------------------------------------------------
    def __eq__(self, other) -> bool:
        return isinstance(other, LinExpr) and other._key == self._key

    def __hash__(self) -> int:
        return self._hash

    def __repr__(self) -> str:
        parts: list[str] = []
        for name, coeff in sorted(self.coeffs.items()):
            if coeff == 1:
                parts.append(f"+ {name}")
            elif coeff == -1:
                parts.append(f"- {name}")
            elif coeff > 0:
                parts.append(f"+ {coeff}*{name}")
            else:
                parts.append(f"- {-coeff}*{name}")
        if self.const or not parts:
            parts.append(f"+ {self.const}" if self.const >= 0 else f"- {-self.const}")
        text = " ".join(parts)
        return text[2:] if text.startswith("+ ") else text.replace("- ", "-", 1)


# ---------------------------------------------------------------------------
# Constraints
# ---------------------------------------------------------------------------

EQ = "=="
GE = ">="
CONG = "cong"


class Constraint:
    """A normalised atom: ``lin == 0``, ``lin >= 0`` or ``lin = 0 (mod m)``."""

    __slots__ = ("lin", "op", "modulus", "_hash")

    def __init__(self, lin: LinExpr, op: str, modulus: int = 0):
        self.lin = lin
        self.op = op
        self.modulus = modulus
        self._hash = hash((lin, op, modulus))

    # -- normalising constructors ------------------------------------------
    @staticmethod
    def equality(lin: LinExpr) -> "Constraint":
        scaled = lin.scale(lin.integer_multiplier())
        divisor = _content(scaled)
        if divisor > 1:
            scaled = scaled.scale(Fraction(1, divisor))
        if scaled.is_constant():
            return TRUE_CONSTRAINT if scaled.const == 0 else FALSE_CONSTRAINT
        if scaled.const.denominator != 1:
            # gcd of the coefficients does not divide the constant: no integer
            # solution exists.
            return FALSE_CONSTRAINT
        scaled = _canonical_sign(scaled)
        return Constraint(scaled, EQ)

    @staticmethod
    def at_least_zero(lin: LinExpr) -> "Constraint":
        """``lin >= 0`` with integer tightening."""
        scaled = lin.scale(lin.integer_multiplier())
        divisor = _content(scaled)
        if divisor > 1:
            scaled = LinExpr(
                {n: c / divisor for n, c in scaled.coeffs.items()},
                _floor(scaled.const / divisor),
            )
        if scaled.is_constant():
            return TRUE_CONSTRAINT if scaled.const >= 0 else FALSE_CONSTRAINT
        return Constraint(scaled, GE)

    @staticmethod
    def greater_zero(lin: LinExpr) -> "Constraint":
        """``lin > 0`` -- integral, hence ``lin - 1 >= 0``."""
        scaled = lin.scale(lin.integer_multiplier())
        return Constraint.at_least_zero(scaled - LinExpr.constant(1))

    @staticmethod
    def congruence(lin: LinExpr, modulus: int) -> "Constraint":
        modulus = abs(int(modulus))
        if modulus in (0, 1):
            return TRUE_CONSTRAINT
        if lin.integer_multiplier() != 1:
            return TRUE_CONSTRAINT  # not an integral expression: no information
        coeffs = {n: Fraction(int(c) % modulus) for n, c in lin.coeffs.items()}
        reduced = LinExpr(coeffs, int(lin.const) % modulus)
        if reduced.is_constant():
            return TRUE_CONSTRAINT if reduced.const == 0 else FALSE_CONSTRAINT
        divisor = gcd(_content(reduced), modulus)
        if divisor > 1:
            if int(reduced.const) % divisor != 0:
                return FALSE_CONSTRAINT
            reduced = LinExpr(
                {n: c / divisor for n, c in reduced.coeffs.items()},
                int(reduced.const) // divisor,
            )
            modulus //= divisor
            if modulus == 1:
                return TRUE_CONSTRAINT
        return Constraint(reduced, CONG, modulus)

    # -- derived operations -------------------------------------------------
    def substitute(self, var: str, replacement: LinExpr) -> "Constraint":
        if var not in self.lin.coeffs:
            return self
        new_lin = self.lin.substitute(var, replacement)
        return self._rebuild(new_lin)

    def rename(self, mapping: dict[str, str]) -> "Constraint":
        return self._rebuild(self.lin.rename(mapping))

    def _rebuild(self, lin: LinExpr) -> "Constraint":
        if self.op == EQ:
            return Constraint.equality(lin)
        if self.op == GE:
            return Constraint.at_least_zero(lin)
        return Constraint.congruence(lin, self.modulus)

    def negate(self) -> list["Constraint"]:
        """Disjunction of constraints equivalent to ``not self``."""
        if self.op == EQ:
            return [
                Constraint.greater_zero(self.lin),
                Constraint.greater_zero(self.lin.negate()),
            ]
        if self.op == GE:
            return [Constraint.greater_zero(self.lin.negate())]
        return [
            Constraint.congruence(self.lin - LinExpr.constant(r), self.modulus)
            for r in range(1, self.modulus)
        ]

    def variables(self) -> Iterable[str]:
        return self.lin.variables()

    def is_trivially_true(self) -> bool:
        if not self.lin.is_constant():
            return False
        if self.op == EQ:
            return self.lin.const == 0
        if self.op == GE:
            return self.lin.const >= 0
        return int(self.lin.const) % self.modulus == 0

    def is_trivially_false(self) -> bool:
        return self.lin.is_constant() and not self.is_trivially_true()

    # -- object protocol ---------------------------------------------------
    def __eq__(self, other) -> bool:
        return (
            isinstance(other, Constraint)
            and other.op == self.op
            and other.modulus == self.modulus
            and other.lin == self.lin
        )

    def __hash__(self) -> int:
        return self._hash

    def __repr__(self) -> str:
        if self.op == CONG:
            return f"{self.lin!r} = 0 (mod {self.modulus})"
        return f"{self.lin!r} {self.op} 0"


TRUE_CONSTRAINT = Constraint(LinExpr.constant(0), GE)
FALSE_CONSTRAINT = Constraint(LinExpr.constant(-1), GE)


def _content(lin: LinExpr) -> int:
    """gcd of the (integral) coefficients of ``lin``; 1 if there are none."""
    result = 0
    for coeff in lin.coeffs.values():
        if coeff.denominator != 1:
            return 1
        result = gcd(result, abs(int(coeff)))
    return result or 1


def _canonical_sign(lin: LinExpr) -> LinExpr:
    """Make the lexicographically first coefficient positive (for equalities)."""
    for name in sorted(lin.coeffs):
        return lin if lin.coeffs[name] > 0 else lin.negate()
    return lin


def _floor(value: Fraction) -> int:
    return value.numerator // value.denominator


def _ceil(value: Fraction) -> int:
    return -((-value.numerator) // value.denominator)


def simplify_constraints(constraints: Iterable[Constraint]) -> frozenset[Constraint]:
    """Drop tautologies; collapse to ``{FALSE}`` if an atom is unsatisfiable."""
    result: set[Constraint] = set()
    for constraint in constraints:
        if constraint.is_trivially_true():
            continue
        if constraint.is_trivially_false():
            return frozenset({FALSE_CONSTRAINT})
        result.add(constraint)
    return frozenset(result)


def constraint_variables(constraints: Iterable[Constraint]) -> set[str]:
    out: set[str] = set()
    for constraint in constraints:
        out.update(constraint.variables())
    return out


def format_constraints(constraints: Iterable[Constraint]) -> str:
    items = sorted(repr(c) for c in constraints)
    return " & ".join(items) if items else "true"


# ---------------------------------------------------------------------------
# Decision procedure
# ---------------------------------------------------------------------------


def _apply_substitutions(lin: LinExpr, subs: dict[str, LinExpr]) -> LinExpr:
    if not subs:
        return lin
    result = lin
    for name in list(result.coeffs):
        replacement = subs.get(name)
        if replacement is not None:
            result = result.substitute(name, replacement)
    return result


def _solve_congruence(a: int, k: int, modulus: int) -> Optional[tuple[int, int]]:
    """Solve ``a*v + k = 0 (mod modulus)``; return ``(residue, modulus)``."""
    a %= modulus
    target = (-k) % modulus
    divisor = gcd(a, modulus)
    if divisor == 0:
        return (0, 1) if target == 0 else None
    if target % divisor != 0:
        return None
    reduced_modulus = modulus // divisor
    if reduced_modulus == 1:
        return (0, 1)
    inverse = pow(a // divisor, -1, reduced_modulus)
    return ((target // divisor) * inverse % reduced_modulus, reduced_modulus)


def _merge_congruences(
    first: tuple[int, int], second: tuple[int, int]
) -> Optional[tuple[int, int]]:
    """Chinese remainder theorem for two residue classes."""
    r1, m1 = first
    r2, m2 = second
    divisor = gcd(m1, m2)
    if (r1 - r2) % divisor != 0:
        return None
    lcm = m1 // divisor * m2
    if lcm == 0:
        return (0, 1)
    step = m1 // divisor
    inverse = pow(step % (m2 // divisor) or 1, -1, m2 // divisor) if m2 // divisor > 1 else 0
    factor = ((r2 - r1) // divisor * inverse) % (m2 // divisor) if m2 // divisor > 1 else 0
    return ((r1 + m1 * factor) % lcm, lcm)


class LinearSolver:
    """Satisfiability / implication checks for conjunctions of constraints."""

    def __init__(self, fm_limit: int = 3000, cache_limit: int = 400_000):
        self.fm_limit = fm_limit
        self.cache_limit = cache_limit
        self._sat_cache: dict[frozenset, bool] = {}
        self.stats = {"sat_calls": 0, "cache_hits": 0, "unsat": 0, "gave_up": 0}

    # -- satisfiability -----------------------------------------------------
    def is_sat(self, constraints: Iterable[Constraint]) -> bool:
        key = constraints if isinstance(constraints, frozenset) else frozenset(constraints)
        cached = self._sat_cache.get(key)
        if cached is not None:
            self.stats["cache_hits"] += 1
            return cached
        self.stats["sat_calls"] += 1
        result = self._decide(key)
        if not result:
            self.stats["unsat"] += 1
        if len(self._sat_cache) < self.cache_limit:
            self._sat_cache[key] = result
        return result

    def is_unsat(self, constraints: Iterable[Constraint]) -> bool:
        return not self.is_sat(constraints)

    def _decide(self, constraints: frozenset) -> bool:
        equalities: list[Constraint] = []
        inequalities: list[Constraint] = []
        congruences: list[Constraint] = []
        for constraint in constraints:
            if constraint.is_trivially_false():
                return False
            if constraint.is_trivially_true():
                continue
            if constraint.op == EQ:
                equalities.append(constraint)
            elif constraint.op == GE:
                inequalities.append(constraint)
            else:
                congruences.append(constraint)

        subs = self._gauss(equalities)
        if subs is None:
            return False

        rows: list[LinExpr] = []
        for constraint in inequalities:
            lin = _apply_substitutions(constraint.lin, subs)
            normalised = Constraint.at_least_zero(lin)
            if normalised.is_trivially_false():
                return False
            if normalised.is_trivially_true():
                continue
            rows.append(normalised.lin)

        residues: dict[str, tuple[int, int]] = {}
        for constraint in congruences:
            lin = _apply_substitutions(constraint.lin, subs)
            normalised = Constraint.congruence(lin, constraint.modulus)
            if normalised.is_trivially_false():
                return False
            if normalised.is_trivially_true():
                continue
            names = list(normalised.lin.coeffs)
            if len(names) != 1:
                continue  # multi-variable congruence: no cheap reasoning
            name = names[0]
            coeff = normalised.lin.coeffs[name]
            constant = normalised.lin.const
            if coeff.denominator != 1 or constant.denominator != 1:
                continue
            solved = _solve_congruence(int(coeff), int(constant), normalised.modulus)
            if solved is None:
                return False
            previous = residues.get(name)
            if previous is None:
                residues[name] = solved
            else:
                merged = _merge_congruences(previous, solved)
                if merged is None:
                    return False
                residues[name] = merged

        if residues and not self._congruences_within_bounds(rows, residues):
            return False

        return self._fourier_motzkin(rows)

    def _gauss(self, equalities: Sequence[Constraint]) -> Optional[dict[str, LinExpr]]:
        """Triangular substitution map, or ``None`` if the system is unsatisfiable."""
        subs: dict[str, LinExpr] = {}
        for constraint in equalities:
            lin = _apply_substitutions(constraint.lin, subs)
            normalised = Constraint.equality(lin)
            if normalised.is_trivially_true():
                continue
            if normalised.is_trivially_false():
                return None
            lin = normalised.lin
            pivot = None
            for name in sorted(lin.coeffs):
                if abs(lin.coeffs[name]) == 1:
                    pivot = name
                    break
            if pivot is None:
                pivot = sorted(lin.coeffs)[0]
            coeff = lin.coeffs[pivot]
            rest = LinExpr(
                {n: c for n, c in lin.coeffs.items() if n != pivot}, lin.const
            )
            replacement = rest.scale(Fraction(-1) / coeff)
            subs = {
                name: expr.substitute(pivot, replacement) for name, expr in subs.items()
            }
            subs[pivot] = replacement
        return subs

    def _congruences_within_bounds(
        self, rows: Sequence[LinExpr], residues: dict[str, tuple[int, int]]
    ) -> bool:
        """Reject residue classes that no integer inside the bounds satisfies."""
        for name, (residue, modulus) in residues.items():
            low, high = _single_variable_bounds(rows, name)
            if low is None or high is None:
                continue
            if low > high:
                return False
            if high - low + 1 >= modulus:
                continue
            if not any(
                value % modulus == residue % modulus for value in range(low, high + 1)
            ):
                return False
        return True

    def _fourier_motzkin(self, rows: Sequence[LinExpr]) -> bool:
        current = list(dict.fromkeys(rows))
        rounds = 0
        while current:
            rounds += 1
            if rounds > 200:  # pragma: no cover - safety valve
                self.stats["gave_up"] += 1
                return True
            variables: set[str] = set()
            for row in current:
                variables.update(row.coeffs)
            if not variables:
                return all(row.const >= 0 for row in current)

            best: Optional[tuple[int, str, int, int]] = None
            for name in sorted(variables):
                positive = sum(1 for row in current if row.coeff(name) > 0)
                negative = sum(1 for row in current if row.coeff(name) < 0)
                cost = positive * negative
                if best is None or cost < best[0]:
                    best = (cost, name, positive, negative)
            cost, var, positive, negative = best  # type: ignore[misc]

            lower = [row for row in current if row.coeff(var) > 0]
            upper = [row for row in current if row.coeff(var) < 0]
            remaining = [row for row in current if row.coeff(var) == 0]

            if positive and negative:
                if len(remaining) + cost > self.fm_limit:  # pragma: no cover
                    self.stats["gave_up"] += 1
                    return True
                for low_row in lower:
                    a = low_row.coeff(var)
                    for high_row in upper:
                        b = -high_row.coeff(var)
                        combined = Constraint.at_least_zero(
                            low_row.scale(b) + high_row.scale(a)
                        )
                        if combined.is_trivially_false():
                            return False
                        if combined.is_trivially_true():
                            continue
                        remaining.append(combined.lin)

            for row in remaining:
                if row.is_constant() and row.const < 0:
                    return False
            current = list(
                dict.fromkeys(row for row in remaining if not row.is_constant())
            )
        return True

    # -- implication --------------------------------------------------------
    def implies(
        self, constraints: Iterable[Constraint], target: Constraint
    ) -> bool:
        """Does the conjunction of ``constraints`` entail ``target``?"""
        if target.is_trivially_true():
            return True
        base = frozenset(constraints)
        if target in base:
            return True
        if target.op == CONG and target.modulus > 64:
            return False  # too expensive to enumerate
        for negated in target.negate():
            if self.is_sat(base | {negated}):
                return False
        return True

    def implies_all(
        self, constraints: Iterable[Constraint], targets: Iterable[Constraint]
    ) -> bool:
        base = frozenset(constraints)
        if not self.is_sat(base):
            return True  # bottom implies everything
        return all(self.implies(base, target) for target in targets)

    # -- value / bound extraction ------------------------------------------
    def derive_values(self, constraints: Iterable[Constraint]) -> dict[str, Fraction]:
        """Variables whose value is uniquely fixed by the equalities."""
        equalities = [c for c in constraints if c.op == EQ]
        subs = self._gauss(equalities)
        if subs is None:
            return {}
        known = {
            name: expr.const for name, expr in subs.items() if expr.is_constant()
        }
        # A variable pinned from both sides by inequalities is known as well.
        rows = []
        for constraint in constraints:
            if constraint.op == GE:
                lin = _apply_substitutions(constraint.lin, subs)
                if not lin.is_constant():
                    rows.append(lin)
        for name in list(constraint_variables(constraints)):
            if name in known:
                continue
            low, high = _single_variable_bounds(rows, name)
            if low is not None and high is not None and low == high:
                known[name] = Fraction(low)
        return known

    def bounds(
        self, constraints: Iterable[Constraint], var: str
    ) -> tuple[Optional[int], Optional[int]]:
        known = self.derive_values(constraints)
        if var in known:
            value = known[var]
            if value.denominator == 1:
                return int(value), int(value)
        rows: list[LinExpr] = []
        for constraint in constraints:
            if constraint.op != GE:
                continue
            lin = constraint.lin
            substituted = LinExpr(dict(lin.coeffs), lin.const)
            for name, value in known.items():
                if name != var and name in substituted.coeffs:
                    substituted = substituted.substitute(
                        name, LinExpr.constant(value)
                    )
            rows.append(substituted)
        return _single_variable_bounds(rows, var)

    def congruence_of(
        self, constraints: Iterable[Constraint], lin: LinExpr, modulus: int
    ) -> Optional[int]:
        """Residue of ``lin`` modulo ``modulus`` if it is uniquely determined."""
        modulus = abs(int(modulus))
        if modulus <= 1:
            return 0
        if modulus > 64:
            return None
        base = frozenset(constraints)
        value = lin.evaluate(self.derive_values(base))
        if value is not None and value.denominator == 1:
            return int(value) % modulus
        for residue in range(modulus):
            candidate = Constraint.congruence(
                lin - LinExpr.constant(residue), modulus
            )
            if self.implies(base, candidate):
                return residue
        return None

    def is_nonnegative(self, constraints: Iterable[Constraint], lin: LinExpr) -> bool:
        return self.implies(frozenset(constraints), Constraint.at_least_zero(lin))

    # -- model search -------------------------------------------------------
    def find_model(
        self,
        constraints: Iterable[Constraint],
        variables: Iterable[str] = (),
        width: int = 8,
        node_limit: int = 4000,
    ) -> Optional[dict[str, int]]:
        """Search for a concrete integer assignment satisfying ``constraints``."""
        base = simplify_constraints(constraints)
        if not self.is_sat(base):
            return None
        wanted = set(variables) | constraint_variables(base)
        budget = [node_limit]

        def recurse(current: frozenset, pending: list[str]) -> Optional[dict[str, int]]:
            if budget[0] <= 0:
                return None
            known = self.derive_values(current)
            unresolved = [
                name
                for name in pending
                if name not in known or known[name].denominator != 1
            ]
            if not unresolved:
                model = {}
                for name in wanted:
                    value = known.get(name)
                    if value is None or value.denominator != 1:
                        return None
                    model[name] = int(value)
                return model if self._verify_model(base, model) else None
            name = unresolved[0]
            low, high = self.bounds(current, name)
            for candidate in _candidate_values(low, high, width):
                budget[0] -= 1
                if budget[0] <= 0:
                    return None
                extended = current | {
                    Constraint.equality(
                        LinExpr.variable(name) - LinExpr.constant(candidate)
                    )
                }
                if not self.is_sat(extended):
                    continue
                found = recurse(extended, unresolved[1:])
                if found is not None:
                    return found
            return None

        return recurse(base, sorted(wanted))

    def _verify_model(self, constraints: Iterable[Constraint], model: dict[str, int]) -> bool:
        for constraint in constraints:
            value = constraint.lin.evaluate(model)
            if value is None:
                return False
            if constraint.op == EQ and value != 0:
                return False
            if constraint.op == GE and value < 0:
                return False
            if constraint.op == CONG and int(value) % constraint.modulus != 0:
                return False
        return True


def _single_variable_bounds(
    rows: Sequence[LinExpr], var: str
) -> tuple[Optional[int], Optional[int]]:
    low: Optional[int] = None
    high: Optional[int] = None
    for row in rows:
        coeff = row.coeff(var)
        if coeff == 0 or len(row.coeffs) != 1:
            continue
        # coeff * var + const >= 0
        if coeff > 0:
            candidate = _ceil(-row.const / coeff)
            low = candidate if low is None else max(low, candidate)
        else:
            candidate = _floor(-row.const / coeff)
            high = candidate if high is None else min(high, candidate)
    return low, high


def _candidate_values(
    low: Optional[int], high: Optional[int], width: int
) -> list[int]:
    candidates: list[int] = []

    def push(value: int) -> None:
        if low is not None and value < low:
            return
        if high is not None and value > high:
            return
        if value not in candidates:
            candidates.append(value)

    if low is not None:
        for offset in range(width):
            push(low + offset)
    if high is not None:
        for offset in range(width):
            push(high - offset)
    push(0)
    for offset in range(1, width + 1):
        push(offset)
        push(-offset)
    return candidates


# ---------------------------------------------------------------------------
# Existential quantification
# ---------------------------------------------------------------------------


def eliminate_variable(
    constraints: Iterable[Constraint], var: str
) -> frozenset[Constraint]:
    """Existentially quantify ``var`` away.

    Elimination through an equality is exact; otherwise Fourier-Motzkin is used
    for the inequalities and congruences mentioning ``var`` are dropped (a sound
    weakening).
    """
    items = list(constraints)
    equalities = [c for c in items if c.op == EQ and var in c.lin.coeffs]
    if equalities:
        chosen = min(
            equalities,
            key=lambda c: (abs(c.lin.coeffs[var]) != 1, len(c.lin.coeffs)),
        )
        coeff = chosen.lin.coeffs[var]
        rest = LinExpr(
            {n: c for n, c in chosen.lin.coeffs.items() if n != var}, chosen.lin.const
        )
        replacement = rest.scale(Fraction(-1) / coeff)
        out = [c.substitute(var, replacement) for c in items if c is not chosen]
        return simplify_constraints(out)

    keep = [c for c in items if var not in c.lin.coeffs]
    lower = [c.lin for c in items if c.op == GE and c.lin.coeff(var) > 0]
    upper = [c.lin for c in items if c.op == GE and c.lin.coeff(var) < 0]
    for low_row in lower:
        a = low_row.coeff(var)
        for high_row in upper:
            b = -high_row.coeff(var)
            keep.append(Constraint.at_least_zero(low_row.scale(b) + high_row.scale(a)))
    return simplify_constraints(keep)


def eliminate_variables(
    constraints: Iterable[Constraint], variables: Iterable[str]
) -> frozenset[Constraint]:
    result = frozenset(constraints)
    for var in variables:
        result = eliminate_variable(result, var)
    return result


def rename_variable(
    constraints: Iterable[Constraint], source: str, target: str
) -> frozenset[Constraint]:
    mapping = {source: target}
    return simplify_constraints(c.rename(mapping) for c in constraints)


# ---------------------------------------------------------------------------
# Translation of C expressions into linear constraints
# ---------------------------------------------------------------------------

MAX_DNF_CLAUSES = 64


def next_aux_index(names: Iterable[str], prefix: str) -> int:
    pattern = re.compile("^" + re.escape(prefix) + r"(\d+)$")
    best = 0
    for name in names:
        match = pattern.match(name)
        if match:
            best = max(best, int(match.group(1)) + 1)
    return best


class LinearizeContext:
    """Context for :func:`linearize` / :func:`to_dnf`.

    It knows the constraints that already hold (used to resolve non-linear
    sub-terms), maps program variables to symbol names (used for the SSA
    encoding of program paths) and collects the auxiliary facts introduced for
    terms the linear domain cannot represent exactly.
    """

    def __init__(
        self,
        solver: LinearSolver,
        constraints: Iterable[Constraint] = (),
        env: Optional[dict[str, str]] = None,
        prefix: str = "__t",
    ):
        self.solver = solver
        self.constraints = frozenset(constraints)
        self.env = dict(env or {})
        self.prefix = prefix
        self.extra: list[Constraint] = []
        self.approximated = False
        self._counter = next_aux_index(
            set(constraint_variables(self.constraints)) | set(self.env.values()), prefix
        )
        self._known: Optional[dict[str, Fraction]] = None

    # -- naming -------------------------------------------------------------
    def symbol(self, name: str) -> str:
        return self.env.get(name, name)

    def new_symbol(self) -> str:
        name = f"{self.prefix}{self._counter}"
        self._counter += 1
        return name

    def fresh_unconstrained(self) -> LinExpr:
        return LinExpr.variable(self.new_symbol())

    # -- facts --------------------------------------------------------------
    def facts(self) -> frozenset[Constraint]:
        return self.constraints | frozenset(self.extra)

    def add_fact(self, constraint: Constraint) -> None:
        if not constraint.is_trivially_true():
            self.extra.append(constraint)
            self._known = None

    def known(self) -> dict[str, Fraction]:
        if self._known is None:
            self._known = self.solver.derive_values(self.facts())
        return self._known

    def value_of(self, lin: LinExpr) -> Optional[Fraction]:
        if lin.is_constant():
            return lin.const
        return lin.evaluate(self.known())

    def integer_value_of(self, lin: LinExpr) -> Optional[int]:
        value = self.value_of(lin)
        if value is None or value.denominator != 1:
            return None
        return int(value)

    def congruence_of(self, lin: LinExpr, modulus: int) -> Optional[int]:
        return self.solver.congruence_of(self.facts(), lin, modulus)

    def is_nonnegative(self, lin: LinExpr) -> bool:
        return self.solver.is_nonnegative(self.facts(), lin)

    # -- approximation ------------------------------------------------------
    def opaque(self) -> LinExpr:
        """A fresh unconstrained symbol standing for an unrepresentable term."""
        self.approximated = True
        return self.fresh_unconstrained()

    def opaque_boolean(self) -> LinExpr:
        lin = self.opaque()
        self.add_fact(Constraint.at_least_zero(lin))
        self.add_fact(Constraint.at_least_zero(LinExpr.constant(1) - lin))
        return lin

    def remainder(self, numerator: LinExpr, modulus: int) -> LinExpr:
        """Symbol for ``numerator % modulus`` with the facts C guarantees."""
        lin = self.opaque()
        # t = a % m implies t = a (mod m) and |t| < |m| with the sign of a.
        self.add_fact(Constraint.congruence(lin - numerator, modulus))
        limit = LinExpr.constant(modulus - 1)
        self.add_fact(Constraint.at_least_zero(limit - lin))
        if self.is_nonnegative(numerator):
            self.add_fact(Constraint.at_least_zero(lin))
        else:
            self.add_fact(Constraint.at_least_zero(lin + limit))
        return lin

    def truth_of(self, expr: Expr) -> Optional[bool]:
        """Decide a boolean expression under the current facts, if possible."""
        facts = self.facts()
        positive = to_dnf(expr, self, False)
        if not any(self.solver.is_sat(facts | frozenset(c)) for c in positive):
            return False
        negative = to_dnf(expr, self, True)
        if not any(self.solver.is_sat(facts | frozenset(c)) for c in negative):
            return True
        return None


_COMPARISONS = ("==", "!=", "<", "<=", ">", ">=")
_LOGICAL = ("&&", "||")
_NEGATED_COMPARISON = {
    "==": "!=",
    "!=": "==",
    "<": ">=",
    ">=": "<",
    ">": "<=",
    "<=": ">",
}


def linearize(expr: Expr, ctx: LinearizeContext) -> LinExpr:
    """Translate ``expr`` into a linear expression (approximating if needed)."""
    if isinstance(expr, Num):
        return LinExpr.constant(expr.value)
    if isinstance(expr, Var):
        return LinExpr.variable(ctx.symbol(expr.name))
    if isinstance(expr, StringLit):
        return ctx.opaque()
    if isinstance(expr, Call):
        for arg in expr.args:
            linearize(arg, ctx)
        # Both nondeterministic input and unknown functions yield a fresh,
        # completely unconstrained value.
        return ctx.fresh_unconstrained()
    if isinstance(expr, Unary):
        return _linearize_unary(expr, ctx)
    if isinstance(expr, Binary):
        return _linearize_binary(expr, ctx)
    return ctx.opaque()  # pragma: no cover - defensive


def _linearize_unary(expr: Unary, ctx: LinearizeContext) -> LinExpr:
    if expr.op == "!":
        truth = ctx.truth_of(expr.operand)
        if truth is not None:
            return LinExpr.constant(0 if truth else 1)
        return ctx.opaque_boolean()
    inner = linearize(expr.operand, ctx)
    if expr.op == "+":
        return inner
    if expr.op == "-":
        return inner.negate()
    if expr.op == "~":
        value = ctx.integer_value_of(inner)
        if value is not None:
            return LinExpr.constant(~value)
        return ctx.opaque()
    return ctx.opaque()  # pragma: no cover - defensive


def _linearize_binary(expr: Binary, ctx: LinearizeContext) -> LinExpr:
    op = expr.op
    if op in _COMPARISONS or op in _LOGICAL:
        truth = ctx.truth_of(expr)
        if truth is not None:
            return LinExpr.constant(1 if truth else 0)
        return ctx.opaque_boolean()

    left = linearize(expr.left, ctx)
    right = linearize(expr.right, ctx)

    if op == "+":
        return left + right
    if op == "-":
        return left - right
    if op == "*":
        if left.is_constant():
            return right.scale(left.const)
        if right.is_constant():
            return left.scale(right.const)
        left_value = ctx.value_of(left)
        if left_value is not None:
            return right.scale(left_value)
        right_value = ctx.value_of(right)
        if right_value is not None:
            return left.scale(right_value)
        return ctx.opaque()
    if op in ("/", "%"):
        divisor = ctx.integer_value_of(right)
        if divisor is None or divisor == 0:
            return ctx.opaque()
        numerator = ctx.integer_value_of(left)
        if numerator is not None:
            folded = (
                c_div(numerator, divisor) if op == "/" else c_mod(numerator, divisor)
            )
            return LinExpr.constant(folded)
        if op == "/":
            if divisor == 1:
                return left
            if divisor == -1:
                return left.negate()
            return ctx.opaque()
        modulus = abs(divisor)
        residue = ctx.congruence_of(left, modulus)
        if residue == 0:
            return LinExpr.constant(0)
        if residue is not None and ctx.is_nonnegative(left):
            return LinExpr.constant(residue)
        return ctx.remainder(left, modulus)
    # Bit operations and shifts: constant fold or approximate.
    left_value = ctx.integer_value_of(left)
    right_value = ctx.integer_value_of(right)
    if left_value is not None and right_value is not None:
        try:
            if op == "&":
                return LinExpr.constant(left_value & right_value)
            if op == "|":
                return LinExpr.constant(left_value | right_value)
            if op == "^":
                return LinExpr.constant(left_value ^ right_value)
            if op == "<<":
                return LinExpr.constant(left_value << right_value)
            if op == ">>":
                return LinExpr.constant(left_value >> right_value)
        except ValueError:  # pragma: no cover - negative shift
            return ctx.opaque()
    if op == "<<" and right_value is not None and right_value >= 0:
        return left.scale(2 ** right_value)
    return ctx.opaque()


def to_dnf(
    expr: Expr, ctx: LinearizeContext, negated: bool = False
) -> list[list[Constraint]]:
    """Disjunctive normal form of ``expr`` (or of its negation).

    The result is a list of conjunctions (clauses).  ``[[]]`` means *true*:
    nothing is known, which is the sound over-approximation used whenever the
    condition cannot be represented.
    """
    if isinstance(expr, Unary) and expr.op == "!":
        return to_dnf(expr.operand, ctx, not negated)

    if isinstance(expr, Binary) and expr.op in _LOGICAL:
        conjunctive = (expr.op == "&&") != negated
        left = to_dnf(expr.left, ctx, negated)
        right = to_dnf(expr.right, ctx, negated)
        if not conjunctive:
            return _cap_clauses(left + right)
        if len(left) * len(right) > MAX_DNF_CLAUSES:
            return [[]]
        return _cap_clauses([lc + rc for lc in left for rc in right])

    if isinstance(expr, Binary) and expr.op in _COMPARISONS:
        op = _NEGATED_COMPARISON[expr.op] if negated else expr.op
        left = linearize(expr.left, ctx)
        right = linearize(expr.right, ctx)
        difference = left - right
        if op == "==":
            return [[Constraint.equality(difference)]]
        if op == "!=":
            return [
                [Constraint.greater_zero(difference)],
                [Constraint.greater_zero(difference.negate())],
            ]
        if op == ">":
            return [[Constraint.greater_zero(difference)]]
        if op == ">=":
            return [[Constraint.at_least_zero(difference)]]
        if op == "<":
            return [[Constraint.greater_zero(difference.negate())]]
        if op == "<=":
            return [[Constraint.at_least_zero(difference.negate())]]

    # Arithmetic expression used as a condition: true means "different from 0".
    lin = linearize(expr, ctx)
    if negated:
        return [[Constraint.equality(lin)]]
    return [
        [Constraint.greater_zero(lin)],
        [Constraint.greater_zero(lin.negate())],
    ]


def _cap_clauses(clauses: list[list[Constraint]]) -> list[list[Constraint]]:
    if len(clauses) > MAX_DNF_CLAUSES:  # pragma: no cover - safety valve
        return [[]]
    return clauses


def condition_clauses(
    text: str, ctx: LinearizeContext, negated: bool = False
) -> list[list[Constraint]]:
    """Parse ``text`` and return its DNF; ``[[]]`` on syntax problems."""
    try:
        expr = parse_expression(text)
    except (ExpressionSyntaxError, IndexError):  # pragma: no cover - robustness
        return [[]]
    return to_dnf(expr, ctx, negated)

